translate this code's comment to english:

def get\_substitues(substitutes, tokenizer, mlm\_model, use\_bpe, substitutes\_score=None, threshold=3.0):
 '''
 将生成的substitued subwords转化为words
 '''
 # substitues L,k
 # from this matrix to recover a word
 words = []
 sub\_len, k = substitutes.size() # sub-len, k

 if sub\_len == 0:
 # 比如空格对应的subwords就是[a,a]，长度为0
 return words

 elif sub\_len == 1:
 # subwords就是本身
 for (i, j) in zip(substitutes[0], substitutes\_score[0]):
 if threshold != 0 and j < threshold:
 break
 words.append(tokenizer.\_decode([int(i)]))
 # 将id转为token.
 else:
 # word被分解成了多个subwords
 if use\_bpe == 1:
 words = get\_bpe\_substitues(substitutes, tokenizer, mlm\_model)
 else:
 return words
 return words

